from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.db_stats.bts.bts_stats import BTSStats


class BTSCountersStats(BTSStats):
    _counter_db_marker = "DB->decimal properties->device:{device_name}->counter id:{counter_id}->BTS counter"
    _counter_cell_db_marker = "DB->decimal properties->device:{device_name}->cell:{cell}->counter id:{counter_id}->BTS counter"

    def __call__(self):
        for path_to_json_file in self.get_all_results_file_locations(json_file='counters.json'):
            device_name = self.get_device_name_from_pmstats_path(path_to_json_file)
            counter = self.load_stats_file(path_to_json_file)
            self.add_stats_for_particular_device(data=counter, device_name=device_name)

    def add_stats_for_particular_device(self, data, device_name):
        device_stats = {}
        for counter_id in data:
            marker_params = {
                'device_name': device_name,
                'counter_id': counter_id
            }

            for cell_object in data[counter_id]:
                value = data[counter_id][cell_object]
                if value == 'NA':
                    continue
                elif cell_object == 'null':
                    marker = BTSCountersStats._counter_db_marker.format(**marker_params)
                else:
                    marker_params['cell'] = cell_object
                    marker = BTSCountersStats._counter_cell_db_marker.format(**marker_params)

                device_stats[marker] = value

                marker_params.pop('cell', None)

        tc.add_stats(stats=device_stats)
